<?php require_once __DIR__.'/../shared/config.php';require_admin();$page_title='Collection Report';require __DIR__.'/header.php';$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$q=db()->prepare("SELECT COALESCE(s.category,'Other') category,COUNT(*) payments,SUM(p.amount) total FROM payments p LEFT JOIN services s ON p.service_id=s.id WHERE p.status='active' AND DATE(p.payment_datetime) BETWEEN ? AND ? GROUP BY s.category ORDER BY total DESC");$q->execute([$from,$to]);$rows=$q->fetchAll();$total=array_sum(array_column($rows,'total'));?><div class="list-head"><div><span>ADMINISTRATION</span><h2>Collection report</h2><p>Completed active payments by service category.</p></div><a class="primary" href="export.php?from=<?=e($from)?>&to=<?=e($to)?>">Download CSV</a></div><div class="panel"><form class="search"><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><button class="secondary">Apply</button></form><div class="table-wrap"><table><thead><tr><th>Service Category</th><th>Payments</th><th>Collection</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['category'])?></td><td><?=$r['payments']?></td><td class="amount"><?=peso($r['total'])?></td></tr><?php endforeach?><tr><td><strong>Total</strong></td><td></td><td class="amount"><?=peso($total)?></td></tr></tbody></table></div></div><?php require __DIR__.'/footer.php';
